        String expectedHtml = "<p>Hello <b>World</b></p>";

        String actualHtml = convertHtml(html);

        assertEquals(expectedHtml, actualHtml);
    }

    private String convertHtml(String html) {
        HTMLWriter writer = new HTMLWriter();
        return writer.write(html);
    }

    @Test
    public void testStringConversion() {
        String text1 = "Hello";
        String text2 = "World!";

        assertEquals("Hello <b>World</b>", convertText(text1, text2));
    }

    private String convertText(String text1, String text2) {
        return "<p>" + text1 + "</p>" + "<b>" + text2 + "</b>";
    }
}
